import { toWorld, polygonBounds, pointInPolygon } from './date_geo.mjs';
export const SECTOR = Object.freeze({ minX: -150, maxX: 150, minZ: -300, maxZ: -30 });
export const insideSector = (x, z, margin = 0) => x >= SECTOR.minX + margin && x <= SECTOR.maxX - margin && z >= SECTOR.minZ + margin && z <= SECTOR.maxZ - margin;
export const signedArea = ring => ring.reduce((sum, p, i) => { const q = ring[(i + 1) % ring.length]; return sum + p.x * q.z - q.x * p.z; }, 0) / 2;

/** Sutherland–Hodgman; boundary vertices remain exactly on the owned rectangle. */
export function clipRing(input) {
  let ring = input.map(p => ({ x: p.x, z: p.z }));
  if (ring.length > 1 && Math.hypot(ring[0].x-ring.at(-1).x, ring[0].z-ring.at(-1).z) < 1e-7) ring.pop();
  for (const [axis, limit, sign] of [['x',-150,1],['x',150,-1],['z',-300,1],['z',-30,-1]]) {
    const result = [];
    for (let i=0; i<ring.length; i++) {
      const a=ring[i], b=ring[(i+1)%ring.length], ai=sign*(a[axis]-limit)>=0, bi=sign*(b[axis]-limit)>=0;
      if (ai) result.push(a);
      if (ai !== bi) { const t=(limit-a[axis])/(b[axis]-a[axis]); result.push({x:a.x+t*(b.x-a.x),z:a.z+t*(b.z-a.z),[axis]:limit}); }
    }
    ring = result;
  }
  ring = ring.filter((p,i) => Math.hypot(p.x-ring[(i+1)%ring.length].x,p.z-ring[(i+1)%ring.length].z)>1e-5);
  if (ring.length < 3 || Math.abs(signedArea(ring)) < 1) return [];
  return signedArea(ring) < 0 ? ring.reverse() : ring;
}

export function clipSegment(a, b) {
  const dx=b.x-a.x, dz=b.z-a.z; let lo=0, hi=1;
  for (const [p,q] of [[-dx,a.x+150],[dx,150-a.x],[-dz,a.z+300],[dz,-30-a.z]]) {
    if (Math.abs(p)<1e-9) { if(q<0)return null; continue; }
    const t=q/p;
    if(p<0)lo=Math.max(lo,t);else hi=Math.min(hi,t);
    if(lo>hi)return null;
  }
  return [{x:a.x+dx*lo,z:a.z+dz*lo},{x:a.x+dx*hi,z:a.z+dz*hi}];
}

const metres = value => Number.parseFloat(value);
export const BUILDINGS = SOURCE_FEATURES.filter(f=>f.kind==='building').flatMap(f=>{
  const ring=clipRing(f.points.map(([lat,lon])=>toWorld(lat,lon)));
  if(!ring.length)return [];
  const bounds=polygonBounds(ring), area=Math.abs(signedArea(ring));
  const levels=metres(f.tags['building:levels']) || (area<90?1:f.tags.building==='university'?4:5);
  const total=metres(f.tags.height), roofShape=f.tags['roof:shape'] || (f.tags['roof:levels']==='0'?'flat':area<90?'flat':'mansard');
  const roofHeight=roofShape==='flat'?0.35:metres(f.tags['roof:height'])||3.5;
  const height=total?Math.max(3,total-roofHeight):levels*3.15+0.8;
  return [{id:f.id,tags:f.tags,ring,bounds,levels,height,roofShape,roofHeight,area}];
});
export const insideBuilding = (x,z) => BUILDINGS.some(b=>Math.abs(x-b.bounds.cx)<=b.bounds.hw && Math.abs(z-b.bounds.cz)<=b.bounds.hd && pointInPolygon(x,z,b.ring));

export const STREETS = SOURCE_FEATURES.filter(f=>f.kind==='highway').flatMap(f=>{
  const pts=f.points.map(([lat,lon])=>toWorld(lat,lon)),segments=[];
  for(let i=1;i<pts.length;i++){const seg=clipSegment(pts[i-1],pts[i]);if(seg && Math.hypot(seg[0].x-seg[1].x,seg[0].z-seg[1].z)>.2)segments.push(seg);}
  if(!segments.length)return [];
  const main=['residential','tertiary','secondary','living_street'].includes(f.tags.highway);
  const width=main?(f.tags.name==='Schellingstraße'?10:f.tags.name==='Türkenstraße'?9:7):f.tags.highway==='service'?3.3:2.3;
  return [{id:f.id,name:f.tags.name||'',tags:f.tags,segments,width,main}];
});
export const TREES = SOURCE_FEATURES.filter(f=>f.kind==='tree').map(f=>({id:f.id,...toWorld(...f.point),height:metres(f.tags.height)||8.5})).filter(p=>insideSector(p.x,p.z,3.8)&&!insideBuilding(p.x,p.z));
export function nearestStreet(x,z,mainOnly=true) {
  let best={distance:Infinity};
  for(const street of STREETS) {
    if(mainOnly&&!street.main)continue;
    for(const [a,b] of street.segments){const dx=b.x-a.x,dz=b.z-a.z,len2=dx*dx+dz*dz,t=Math.max(0,Math.min(1,((x-a.x)*dx+(z-a.z)*dz)/len2));const px=a.x+t*dx,pz=a.z+t*dz,distance=Math.hypot(x-px,z-pz);if(distance<best.distance)best={distance,x:px,z:pz,street,dx:dx/Math.sqrt(len2),dz:dz/Math.sqrt(len2)};}
  }
  return best;
}

