export const BICYCLE_PARKING = SOURCE_FEATURES.filter(f=>f.kind==='bicycle_parking').map(f=>({id:f.id,...toWorld(...f.point),capacity:Number(f.tags.capacity)||6})).filter(p=>insideSector(p.x,p.z,2)&&!insideBuilding(p.x,p.z));
